solutions.javascript:
function fibonacci(n, memo = {}) {
  if (n < 2) return n;
  if (memo[n] !== undefined) return memo[n];
  return (memo[n] = fibonacci(n - 1, memo) + fibonacci(n - 2, memo));
}

solutions.python:
def fibonacci(n):
    a, b = 0, 1
    for _ in range(n):
        a, b = b, a + b
    return a

